    private static readonly char[] Separators = [' ', '\n', '\r'];

    public static (double? Current, bool CurrentSent, double? Other, bool OtherSent)[] Pairs() =>
        AfterMove.Split(Separators, StringSplitOptions.RemoveEmptyEntries)
            .Select(pair => pair.Split('/'))
            .Select(p => (Value(p[0]), p[0] != "_", Value(p[1]), p[1] != "_"))
            .ToArray();

    private static double? Value(string s) =>
        s is "_" or "x" ? null : double.Parse(s, System.Globalization.CultureInfo.InvariantCulture);
